  "code": "import re\n\n\n_NON_TARGET_HINTS = (\n    \"weighted average\",\n    \"commercial paper\",\n    \"debt\",\n    \"derivative\",\n    \"options\",\n    \"option\",\n    \"warrant\",\n    \"preferred stock\",\n    \"borrowings\",\n    \"lease\",\n    \"anti-dilutive\",\n)\n\n\ndef rule_cover_page_common_stock_outstanding(doc: dict) -> list[dict]:\n    try:\n        def norm(text: str) -> str:\n            return re.sub(r\"\\s+\", \" \", (text or \"\").replace(\"\\u2019\", \"'\").replace(\"\\xa0\", \" \")).strip()\n\n        def alpha_word_count(text: str) -> int:\n            return len(re.findall(r\"[A-Za-z]+(?:'[A-Za-z]+)?\", text))\n\n        def is_candidate(text: str) -> bool:\n            low = norm(text).lower()\n            if not low or \"outstanding\" not in low:\n                return False\n\n            if any(hint in low for hint in _NON_TARGET_HINTS):\n                if \"common stock\" not in low and \"registrant\" not in low and \"shares\" not in low:\n                    return False\n\n            if \"common stock\" in low:\n                return True\n            if \"registrant\" in low and \"shares\" in low:\n                return True\n            if \"issued and outstanding\" in low and \"share\" in low:\n                return True\n            if \"outstanding as of\" in low and \"share\" in low:\n                return True\n            if \"outstanding at\" in low:\n                return True\n            if \"there were\" in low and \"share\" in low:\n                return True\n            if \"the number of shares\" in low and \"outstanding\" in low:\n                return True\n            return False\n\n        def is_context(text: str) -> bool:\n            low = norm(text).lower()\n            if not low:\n                return False\n            if is_candidate(low):\n                return True\n            if re.fullmatch(r\"[\\d,().$\\-\\s]+\", low):\n                return True\n            if re.search(r\"\\d\", low) and (\"share\" in low or \"stock\" in low):\n                return True\n            if \"as of\" in low and alpha_word_count(low) <= 18:\n                return True\n            if \"common stock\" in low and alpha_word_count(low) <= 18:\n                return True\n            if \"registrant\" in low and alpha_word_count(low) <= 18:\n                return True\n            return False\n\n        def add_window(items: list[dict], idx: int, out: list[dict], seen: set) -> None:\n            start = max(0, idx - 2)\n            end = min(len(items), idx + 4)\n            snippet_lines = []\n            meta = items[idx]\n            for item in items[start:end]:\n                item_text = norm(item.get(\"text\") or \"\")\n                if item_text and is_context(item_text):\n                    snippet_lines.append(item_text)\n            if not snippet_lines:\n                return\n            snippet = \"\\n\".join(snippet_lines).strip()\n            if not snippet:\n                return\n            key = (\n                meta.get(\"page_no\"),\n                meta.get(\"line_no\"),\n                meta.get(\"paragraph_no\"),\n                snippet,\n            )\n            if key in seen:\n                return\n            seen.add(key)\n            out.append(\n                {\n                    \"text\": snippet,\n                    **{k: v for k, v in meta.items() if k in (\"page_no\", \"line_no\", \"paragraph_no\")},\n                }\n            )\n\n        out = []\n        seen = set()\n\n        for source_key in (\"lines\", \"paragraphs\"):\n            items = [item for item in (doc.get(source_key) or []) if isinstance(item, dict)]\n            items.sort(\n                key=lambda d: (\n                    int(d.get(\"page_no\") or 0),\n                    int(d.get(\"line_no\") or d.get(\"paragraph_no\") or 0),\n                )\n            )\n            for idx, item in enumerate(items):\n                text = norm(item.get(\"text\") or \"\")\n                if not text:\n                    continue\n                page_no = item.get(\"page_no\")\n                if page_no is not None and int(page_no) > 2:\n                    continue\n                if is_candidate(text):\n                    add_window(items, idx, out, seen)\n\n        if out:\n            return out\n\n        for item in [p for p in (doc.get(\"pages\") or []) if isinstance(p, dict)]:\n            page_no = item.get(\"page_no\")\n            if page_no is not None and int(page_no) > 2:\n                continue\n            text = norm(item.get(\"text\") or \"\")\n            if not text or not is_candidate(text):\n                continue\n\n            # Page-level fallback. Keep only a local slice around the first hit.\n            m = re.search(r\".{0,180}(?:common stock|outstanding|shares).{0,240}\", text, re.IGNORECASE)\n            snippet = norm(m.group(0)) if m else text[:500]\n            key = (page_no, snippet)\n            if key in seen:\n                continue\n            seen.add(key)\n            out.append({\"page_no\": page_no, \"text\": snippet})\n\n        return out\n    except Exception:\n        return []\n",
